loadstring(game:HttpGet("https://githubusercontent.com"))()
local p = game.Players.LocalPlayer local function m(c) local h = c:WaitForChild("Humanoid") h.WalkSpeed = 90 h.JumpPower = 140 end if p.Character then m(p.Character) end p.CharacterAdded:Connect(m) _G.S = true task.spawn(function() while _G.S do task.wait(0.01) game:GetService("VirtualInputService"):WindowClick(Vector2.new(0, 0), 1) end end) local function e(o) if o:IsA("Model") and (o.Name:lower():find("egg") or o.Name:lower():find("ovo")) then if not o:FindFirstChild("H") then local h = Instance.new("Highlight") h.Name = "H" h.FillColor = Color3.fromHSV(tick()%5/5,1,1) h.Parent = o task.spawn(function() while o and h and h.Parent do h.FillColor = Color3.fromHSV(tick()%5/5,1,1) task.wait(0.05) end end) end end end for _,v in pairs(workspace:GetDescendants()) do e(v) end workspace.DescendantAdded:Connect(e)

